#include <tora/compat/integer_document.hpp>
#include <charconv>
namespace tora::compat {
IntegerDocument IntegerDocument::create(LpDocument lp,std::vector<bool> flags){IntegerDocument d;d.lp=std::move(lp);d.integral=std::move(flags);(void)d.encode();return d;}
IntegerDocument IntegerDocument::decode(std::string_view bytes){if(bytes.size()>ToraLpCodec::MaxFileBytes)throw std::invalid_argument("Integer file exceeds4MiB");std::vector<std::string> records;while(!bytes.empty()){const auto i=bytes.find("\r\n");if(i==std::string_view::npos)throw std::invalid_argument("Integer files require CRLF");records.emplace_back(bytes.substr(0,i));bytes.remove_prefix(i+2);}if(records.size()<8 || records[0]!="5000")throw std::invalid_argument("Select an Integer5000file");const auto count=[](const std::string& text){std::size_t x=0;const auto r=std::from_chars(text.data(),text.data()+text.size(),x);if(r.ec!=std::errc{} || r.ptr!=text.data()+text.size() || !x || x>100)throw std::invalid_argument("Integer size must be1..100");return x;};const auto n=count(records[5]),m=count(records[6]),base=8+(m+5)*(n+2);if(records.size()!=base+n+2)throw std::invalid_argument("Incorrect Integer grid record count");records[0]="3000";std::string lpBytes;for(std::size_t i=0;i<base;++i)lpBytes+=records[i]+"\r\n";IntegerDocument d;d.lp=ToraLpCodec::decode(lpBytes);for(std::size_t j=0;j<n;++j){const auto& r=records[base+j];if(r!="\"y\"" && r!="\"n\"" && r!="\"Y\"" && r!="\"N\"")throw std::invalid_argument("Integer flags must bey/n");d.integral.push_back(r=="\"y\"" || r=="\"Y\"");}for(std::size_t j=0;j<n+2;++j)d.flagRecords_.push_back(records[base+j]);d.originalFlags_=d.integral;return d;}
std::string IntegerDocument::encode()const{const auto n=lp.problem.variables.size();if(integral.size()!=n)throw std::invalid_argument("Integer flag count mismatch");auto bytes=ToraLpCodec::encode(lp);bytes.replace(0,4,"5000");for(std::size_t j=0;j<n;++j)bytes+=(flagRecords_.size()==n+2 && originalFlags_[j]==integral[j]?flagRecords_[j]:integral[j]?"\"y\"":"\"n\"")+std::string("\r\n");for(std::size_t j=n;j<n+2;++j)bytes+=(flagRecords_.size()==n+2?flagRecords_[j]:"\"\"")+std::string("\r\n");if(bytes.size()>ToraLpCodec::MaxFileBytes)throw std::invalid_argument("Integer file exceeds4MiB");return bytes;}
}
